  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm curious — do you have any squares you can share? I need one for my order and I'm pretty low on money right now."
    }
  },
  "rationale": "I need a square to fulfill my order, and since I can't produce it myself (it's not my specialty), I should reach out to B who has the specialty square. Starting a direct conversation is a natural, friendly way to ask."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": ["A"],
      "content": "Hey, I'm working on producing squares since that's my specialty. I'm not sure if you need any, but I can help if you're short on circles. How about we trade? Maybe you can sell me a circle for a fair price?"
    }
  },
  "rationale": "Initiate a low-pressure trade conversation with A to explore mutual benefit, as they have the circle I need for my order and I can offer my specialty shape at a reasonable price."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I'm working on getting a triangle for my order. Since you're the one who makes triangles, I was wondering if you'd be open to trading one for a circle? I can give you $20 for it."
    }
  },
  "rationale": "I need a triangle to fulfill my order, and C is the only one who can produce it. Starting a direct conversation to propose a fair trade makes sense given my limited production capacity and the need to act quickly."
}

